-- Resources content for Bookings' slice 5, partners and agreements
-- (CLAUDE.md, "Resources stay in step with the code"). Content only; the
-- schema is 20261006140000_bookings_partners_agreements.sql. One new guide
-- (the Partners tab, a partner's page and an agreement's page), two guides
-- updated for what the slice changed on their screens (a request's agreement
-- panel and reserved-block picker; reserved blocks on the calendar and the
-- rule's new step), and the release note.

select private.rc_release_guide(
  p_slug => 'bookings-partners',
  p_tool_key => 'bookings',
  p_title => 'Partners and agreements',
  p_summary => 'Partners on file, drafting and approving an agreement, what an agreement draws from the term, and reserving, keeping and releasing blocks.',
  p_screen_keys => array['bookings.partners', 'bookings.partner', 'bookings.agreement'],
  p_sort_order => 27,
  p_version_note => 'Slice 5: partners and agreements',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Partners","marks":[{"type":"bold"}]},{"type":"text","text":" tab lists every UWF unit and outside organization WUWF produces for, with its contact, its agreements and its open requests. Production staff, the Director of Operations or the Executive Director add a partner with "},{"type":"text","text":"+ New partner","marks":[{"type":"bold"}]},{"type":"text","text":"; a request can also name a new partner, and the public form finds or creates one by name."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Agreements"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An agreement is a standing arrangement with one partner: its dates, a "},{"type":"text","text":"reserve share","marks":[{"type":"bold"}]},{"type":"text","text":" in professional hours that its work may draw before being priced incremental, the student hours the partner funds, an airtime allowance in minutes a week, the booking and release deadlines for its reserved blocks, and the framework's notes on direct costs, blackouts, capital and work beyond the envelope."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Draft one from the partner's page with "},{"type":"text","text":"+ Agreement","marks":[{"type":"bold"}]},{"type":"text","text":". A draft reserves nothing and prices nothing. Its page shows "},{"type":"text","text":"what this agreement would draw","marks":[{"type":"bold"}]},{"type":"text","text":" against the active term: the share of the reserve, what would be left for everyone else, the airtime against the envelope, and the windows its blocks would take."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Executive Director approves it with "},{"type":"text","text":"Approve the agreement","marks":[{"type":"bold"}]},{"type":"text","text":". From then on its terms change only with the Executive Director; the notes stay editable. "},{"type":"text","text":"End the agreement","marks":[{"type":"bold"}]},{"type":"text","text":" stops its blocks reserving windows and keeps the pricing already recorded on open requests."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Once active, the page shows consumption bars — the reserve share, funded student hours and airtime drawn by requests under it — and the requests themselves. Attach the signed agreement in the aside; everyone with access can download it."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Reserved blocks"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The director reserves a window on a pool for the partner with "},{"type":"text","text":"Reserve a block","marks":[{"type":"bold"}]},{"type":"text","text":", one date or the same weekday every week to a date. Each block names its booking deadline (when the partner is expected to have a request on it) and its release deadline (when, with no request, it opens to everyone)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A block past its release deadline reads as released on its own; nothing has to be done. "},{"type":"text","text":"Keep","marks":[{"type":"bold"}]},{"type":"text","text":" holds it past that deadline, "},{"type":"text","text":"Release","marks":[{"type":"bold"}]},{"type":"text","text":" opens it early, and "},{"type":"text","text":"Remove","marks":[{"type":"bold"}]},{"type":"text","text":" deletes one that was reserved by mistake. A booked block is freed by releasing the request's date."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"On the calendar a reserved block shows with a dotted frame until it is taken; other partners cannot book that window until its release deadline."}]}]}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'bookings-requests',
  p_tool_key => 'bookings',
  p_title => 'Requests and estimates',
  p_summary => 'A request through five stages: how it is priced, the estimate, planning and holding dates, airtime commitments, agreements, and closing a request.',
  p_screen_keys => array['bookings.requests', 'bookings.project'],
  p_sort_order => 20,
  p_version_note => 'Slice 5: a request under an agreement, and reserved blocks',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Requests","marks":[{"type":"bold"}]},{"type":"text","text":" tab lists every request for university production work. A request moves through five stages — Request, Estimate, Booked, Delivered, Settled — and can be deferred, declined or withdrawn at any point before delivery. Production staff enter a request with "},{"type":"text","text":"+ New request","marks":[{"type":"bold"}]},{"type":"text","text":", naming the partner on file or a new one, what is asked for (production, airtime or both), the event dates and the contact."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"How a request is priced"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Nobody picks a price. The treatment is derived from facts on the request and the estimate says why: a partner outside the university is priced "},{"type":"text","text":"external","marks":[{"type":"bold"}]},{"type":"text","text":"; work recorded as strategic or applied-learning is priced "},{"type":"text","text":"strategic","marks":[{"type":"bold"}]},{"type":"text","text":" when the term's reserve covers its professional hours; everything else is "},{"type":"text","text":"incremental","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Record the strategic judgment on the request's scope (Edit in the Scope panel). "},{"type":"text","text":"Change how it is priced","marks":[{"type":"bold"}]},{"type":"text","text":" lets production staff set a treatment by hand with a reason; pricing a request strategic against its derived treatment draws the reserve and is the Executive Director's call. Every change is recorded."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rates come from the rate card recorded for estimates on the Rates tab, and the estimate keeps the version it was first priced on. While no version is adopted every figure is provisional."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The estimate"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Add a line","marks":[{"type":"bold"}]},{"type":"text","text":" adds a service package (a studio half-day, a basic webcast, a field day), labor hours beyond a package, or a direct expense at cost. A package line carries the package's hours per labor class, which is what the dates draw on."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Plan a date","marks":[{"type":"bold"}]},{"type":"text","text":" adds each window the work needs — pool, date, window and the hours it takes from each class. A planned date takes nothing yet; the page runs the booking rule for every planned date and reads the result as one line, with "},{"type":"text","text":"show the check","marks":[{"type":"bold"}]},{"type":"text","text":" listing any date that would be refused and the nearest open windows."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Send the estimate","marks":[{"type":"bold"}]},{"type":"text","text":" holds every planned date tentatively for 14 days. The holds are placed all or none: a date the rule refuses stops the send and names the reason. Tentative holds count as taken for every other request."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"When the partner approves, "},{"type":"text","text":"Partner approved — book it","marks":[{"type":"bold"}]},{"type":"text","text":" confirms the holds and the request is Booked. An estimate that lapses can be sent again, which re-checks its dates. "},{"type":"text","text":"Mark delivered","marks":[{"type":"bold"}]},{"type":"text","text":" once the work is done."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Airtime"}]},{"type":"paragraph","content":[{"type":"text","text":"A request for airtime records a commitment — airings a week, length, dates, and whether it is contributed from the term's envelope or paid. The page compares contributed commitments across requests with the envelope. The avails themselves are placed in Traffic (a message, as copy on a bonus or paid line) or On Air (a recurring feature, pinned on the clock), never here; once placed, paste the contract's or the pin's id so the request can show what was actually scheduled."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Under an agreement"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A partner with an approved agreement can have a request put under it from the "},{"type":"text","text":"Agreement","marks":[{"type":"bold"}]},{"type":"text","text":" panel on the request's page. The request is then priced against the agreement's reserve share — strategic while the share has hours left, incremental beyond it — and the estimate says so."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Use a reserved block","marks":[{"type":"bold"}]},{"type":"text","text":" turns one of the agreement's reserved windows into a date on the request, planned, held or confirmed to match where the estimate stands. Releasing that date hands the block back to the partner."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A package Finance has scoped to the agreement appears in the package list only for requests under it."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Closing a request"}]},{"type":"paragraph","content":[{"type":"text","text":"Close the request","marks":[{"type":"bold"}]},{"type":"text","text":" defers, declines or withdraws it with a reason. Every hold is released and the stage it reached is kept. Declining an outside partner's request for capacity can record the estimate's margin as foregone for the term report. A closed request can be reopened; its dates must be planned again."}]}]}$body$
);

select private.rc_release_guide(
  p_slug => 'bookings-calendar',
  p_tool_key => 'bookings',
  p_title => 'The calendar and the term plan',
  p_summary => 'The term plan''s two envelopes, each pool''s units and windows, blackouts, holds, bookings and reserved blocks, and the booking rule.',
  p_screen_keys => array['bookings.calendar'],
  p_sort_order => 30,
  p_version_note => 'Slice 5: reserved blocks on the calendar and in the rule',
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The "},{"type":"text","text":"Calendar","marks":[{"type":"bold"}]},{"type":"text","text":" tab shows one term of production work: what WUWF has kept for itself, what partners have booked, and how much of the term's capacity is left. Everything on it is measured in professional hours; a project day is eight."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The term plan"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The Director of Operations creates a term plan from "},{"type":"text","text":"Term plan","marks":[{"type":"bold"}]},{"type":"text","text":": the term's dates, its net professional hours, the reserve share kept for strategic work, the airtime minutes a week the station contributes, and the production lead's hours a day. One plan is active at a time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Each pool (studio, field, live, edit) has its units for the term and the windows a booking may take, such as a studio morning or afternoon. Select "},{"type":"text","text":"Edit","marks":[{"type":"bold"}]},{"type":"text","text":" on a pool's row to change them."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The two envelopes"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Production capacity","marks":[{"type":"bold"}]},{"type":"text","text":" shows net capacity, the reserve left for strategic work, what is spoken for (bookings and holds) and open capacity. Open capacity is net minus the reserve, minus holds, minus incremental and external bookings. Open the month table to see how it is spread across the term."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Airtime envelope","marks":[{"type":"bold"}]},{"type":"text","text":" is read from On Air's clocks: the avails marked as admitting a university announcement, the minutes the station already pins there, the contributed envelope from the term plan, and what is left for Traffic to sell. Airtime is placed in Traffic or On Air, never here."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Blackouts, holds, bookings and reserved blocks"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"blackout","marks":[{"type":"bold"}]},{"type":"text","text":" closes dates to partner work on some or every pool, with a reason. A "},{"type":"text","text":"hold","marks":[{"type":"bold"}]},{"type":"text","text":" is WUWF's own use of one window, core work or maintenance, and takes the lead's hours for that day. The director adds both with "},{"type":"text","text":"+ Blackout","marks":[{"type":"bold"}]},{"type":"text","text":" and "},{"type":"text","text":"+ Hold","marks":[{"type":"bold"}]},{"type":"text","text":"."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"booking","marks":[{"type":"bold"}]},{"type":"text","text":" is a partner's hold on one window. The production lead or the director adds one with "},{"type":"text","text":"+ Booking","marks":[{"type":"bold"}]},{"type":"text","text":". A tentative booking holds the window for 14 days and counts as taken; confirm it or release it from the list under the calendar."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find a slot","marks":[{"type":"bold"}]},{"type":"text","text":" runs the booking rule for a window without booking it, and names the nearest open windows when the one asked for is not available."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A "},{"type":"text","text":"reserved block","marks":[{"type":"bold"}]},{"type":"text","text":" is a window an approved agreement holds for its partner, shown with a dotted frame until the partner's request takes it. Other partners cannot book it until its release deadline; the director keeps or releases blocks from the agreement's page under Partners."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The booking rule"}]},{"type":"paragraph","content":[{"type":"text","text":"Every booking is checked in this order: the date is not blacked out or held for WUWF; the window is not reserved for another partner under an agreement; the window is free, with tentative bookings and reserved blocks counted as taken; the lead's day has room for the hours; and the pricing has capacity. A strategic booking draws the reserve; an incremental or external one draws open capacity. A booking that would take more than half of a month's remaining open hours warns but is not refused. Only the Executive Director can record an exception, and each one is written to the audit log."}]}]}$body$
);

select private.rc_release_note(
  p_slug => 'release-2026-10-06-bookings-partners',
  p_tool_key => 'bookings',
  p_released_on => '2026-10-06',
  p_title => 'Bookings: partners and agreements',
  p_guide_slugs => array['bookings-partners', 'bookings-requests', 'bookings-calendar'],
  p_body => $body${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bookings gains a Partners tab. Every unit or outside organization WUWF produces for has a page with its contact, its requests and its agreements — a standing arrangement with a reserve share, funded student hours, an airtime allowance and reserved blocks on the calendar. Production staff or the director draft an agreement; its page shows what it would draw from the term before the Executive Director approves it. A request can be put under an agreement, which prices it against the agreement's reserve share and lets it take one of the agreement's reserved windows. Reserved blocks hold their windows against other partners until a release deadline, after which they open on their own unless the director keeps them."}]}]}$body$
);
